do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_ch x
   where (select count(*) from public.cities c where c.country_code = 'CH' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one CH row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_ch x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'CH' and c.name = x.city), 'CH',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_ch x;

-- 4b. Key changes on existing hotels: the launch row (labelled 2026) holds the 2025 Key and is
--     relabelled 2025, non-current; the 2026 row is written in 4d
create temp table _kchg_ch (code text primary key, keys smallint, was smallint, launch_year smallint) on commit drop;
insert into _kchg_ch values
    ('hotel_73', 3, 2, 2025),
    ('hotel_81', 3, 2, 2025),
    ('hotel_52', 2, 3, 2025),
    ('hotel_67', 1, 2, 2025);
do $$
declare n int;
begin
  select count(*) into n from _kchg_ch k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was
     and not exists (select 1 from public.award_history o where o.entity_type = 'hotel' and o.entity_id = h.id
                      and o.award_type = 'michelin_keys' and o.guide_year = k.launch_year);
  if n <> 4 then raise exception 'CH: % of 4 Key launch rows found as exported', n; end if;
end $$;
update public.award_history a set guide_year = k.launch_year, is_current = false
  from public.hotels h, _kchg_ch k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_ch k where h.hotel_code = k.code and h.michelin_keys = k.was;

-- 4d. current 2026 Key row for every CH Key hotel that lacks one (new rows, Key changes,
--     and existing rows imported without one)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_55', 'hotel_57', 'hotel_73', 'hotel_51', 'hotel_56', 'hotel_49', 'hotel_50', 'hotel_81', 'hotel_54', 'hotel_53', 'hotel_83', 'hotel_52', 'hotel_79', 'hotel_61', 'hotel_85', 'hotel_77', 'hotel_68', 'hotel_78', 'hotel_70', 'hotel_64', 'hotel_65', 'hotel_63', 'hotel_62', 'hotel_87', 'hotel_74', 'hotel_71', 'hotel_66', 'hotel_76', 'hotel_86', 'hotel_84', 'hotel_2501', 'hotel_82', 'hotel_80', 'hotel_58', 'hotel_2502', 'hotel_69', 'hotel_59', 'hotel_60', 'hotel_72', 'hotel_75', 'hotel_2503', 'hotel_2504', 'hotel_2505', 'hotel_2506', 'hotel_2507', 'hotel_2508', 'hotel_2509', 'hotel_2510', 'hotel_2511', 'hotel_2512', 'hotel_2513', 'hotel_2514', 'hotel_2515', 'hotel_2516', 'hotel_2517', 'hotel_572', 'hotel_2518', 'hotel_2519', 'hotel_2520', 'hotel_2521', 'hotel_2522', 'hotel_2523', 'hotel_2524', 'hotel_2525', 'hotel_67', 'hotel_2526', 'hotel_2527', 'hotel_2528', 'hotel_2529', 'hotel_2530', 'hotel_2531', 'hotel_2532', 'hotel_570', 'hotel_2533', 'hotel_2534', 'hotel_2535', 'hotel_2536', 'hotel_571', 'hotel_2537', 'hotel_2538', 'hotel_2539', 'hotel_2540', 'hotel_2541', 'hotel_2542', 'hotel_2543', 'hotel_2544', 'hotel_2545', 'hotel_2546', 'hotel_2547'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

