do $$
declare n int;
begin
  select count(*) into n from _links_ch l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_ch l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN Guide Switzerland 2025 (Lausanne, 20 October 2025), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 3;
  if n <> 4 then raise exception 'CH: expected 4 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 2;
  if n <> 27 then raise exception 'CH: expected 27 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 1;
  if n <> 103 then raise exception 'CH: expected 103 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CH'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'CH: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CH' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'CH: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CH' and ah.guide_year > 2025;
  if n <> 0 then raise exception 'CH: % current star rows labelled after the 2025 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CH' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'CH: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'CH' and michelin_keys = 3;
  if n <> 10 then raise exception 'CH: expected 10 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'CH' and michelin_keys = 2;
  if n <> 31 then raise exception 'CH: expected 31 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'CH' and michelin_keys = 1;
  if n <> 48 then raise exception 'CH: expected 48 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'CH' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'CH: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

