do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_at x
   where (select count(*) from public.cities c where c.country_code = 'AT' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one AT row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_at x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'AT' and c.name = x.city), 'AT',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_at x;

-- 4b. Key changes on existing hotels: the launch row (labelled 2026) holds the 2025 Key and is
--     relabelled 2025, non-current; the 2026 row is written in 4d
create temp table _kchg_at (code text primary key, keys smallint, was smallint, launch_year smallint) on commit drop;
insert into _kchg_at values
    ('hotel_123', 2, 1, 2025);
do $$
declare n int;
begin
  select count(*) into n from _kchg_at k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was
     and not exists (select 1 from public.award_history o where o.entity_type = 'hotel' and o.entity_id = h.id
                      and o.award_type = 'michelin_keys' and o.guide_year = k.launch_year);
  if n <> 1 then raise exception 'AT: % of 1 Key launch rows found as exported', n; end if;
end $$;
update public.award_history a set guide_year = k.launch_year, is_current = false
  from public.hotels h, _kchg_at k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_at k where h.hotel_code = k.code and h.michelin_keys = k.was;

-- 4d. current 2026 Key row for every AT Key hotel that lacks one (new rows, Key changes,
--     and existing rows imported without one)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_30', 'hotel_29', 'hotel_42', 'hotel_38', 'hotel_2548', 'hotel_31', 'hotel_43', 'hotel_32', 'hotel_34', 'hotel_36', 'hotel_44', 'hotel_45', 'hotel_41', 'hotel_40', 'hotel_2549', 'hotel_35', 'hotel_46', 'hotel_47', 'hotel_39', 'hotel_123', 'hotel_37', 'hotel_48', 'hotel_33', 'hotel_2550', 'hotel_144', 'hotel_2551', 'hotel_2552', 'hotel_125', 'hotel_127', 'hotel_135', 'hotel_2553', 'hotel_119', 'hotel_2554', 'hotel_140', 'hotel_128', 'hotel_122', 'hotel_126', 'hotel_2555', 'hotel_141', 'hotel_145', 'hotel_2556', 'hotel_2557', 'hotel_124', 'hotel_2558', 'hotel_2559', 'hotel_2560', 'hotel_131', 'hotel_137', 'hotel_2561', 'hotel_2562', 'hotel_2563', 'hotel_2564', 'hotel_129', 'hotel_132', 'hotel_2565', 'hotel_2566', 'hotel_146', 'hotel_138', 'hotel_139', 'hotel_2567', 'hotel_134', 'hotel_136', 'hotel_120', 'hotel_130', 'hotel_133', 'hotel_143', 'hotel_2568', 'hotel_121', 'hotel_2569', 'hotel_2570', 'hotel_2571', 'hotel_142'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

