create temp table _links_at (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
insert into _links_at values
    ('hotel_2548', 'rest_3622', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/vienna/anantara-palais-hansen-vienna-hotel-15401 (Anantara Palais Hansen Vienna Hotel), a 2-Key hotel; restaurant pin 56 m from the hotel''s MICHELIN pin. 2026-10-30.'),
    ('hotel_133', 'rest_3649', 'campus', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/kitzbuhel/schwarzer-adler-kitzbuhel-13942 (Schwarzer Adler Kitzbühel), a 1-Key hotel; restaurant pin 415 m from the hotel''s MICHELIN pin. 2026-10-30.'),
    ('hotel_130', 'rest_3669', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/Ischgl-2/schlosshotel-ischgl-13941 (Schlosshotel Ischgl), a 1-Key hotel; restaurant pin 50 m from the hotel''s MICHELIN pin. 2026-10-30.');
do $$
declare n int;
begin
  select count(*) into n from _links_at l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_at l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN Guide Austria 2026 (18 March 2026), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'AT' and michelin_stars = 3;
  if n <> 2 then raise exception 'AT: expected 2 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'AT' and michelin_stars = 2;
  if n <> 19 then raise exception 'AT: expected 19 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'AT' and michelin_stars = 1;
  if n <> 78 then raise exception 'AT: expected 78 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'AT'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'AT: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'AT' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'AT: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'AT' and ah.guide_year > 2026;
  if n <> 0 then raise exception 'AT: % current star rows labelled after the 2026 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'AT' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'AT: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'AT' and michelin_keys = 3;
  if n <> 2 then raise exception 'AT: expected 2 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'AT' and michelin_keys = 2;
  if n <> 21 then raise exception 'AT: expected 21 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'AT' and michelin_keys = 1;
  if n <> 49 then raise exception 'AT: expected 49 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'AT' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'AT: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

-- ============================================================
-- DK: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026)
-- ============================================================

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'DK';
  if n <> 9 then raise exception 'DK: expected 9 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0297', 'Alchemist'), ('rest_0323', 'Kadeau'), ('rest_0473', 'Geranium'), ('rest_0474', 'Jordnær'), ('rest_0475', 'a|o|c'), ('rest_0476', 'Koan'), ('rest_0477', 'Kong Hans Kælder'), ('rest_0478', 'Frederikshøj'), ('rest_0479', 'Henne Kirkeby Kro')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'DK');
  if n <> 0 then raise exception 'DK: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'DK';
  if n <> 0 then raise exception 'DK: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 3683 and 3714) then
    raise exception 'restaurant codes rest_3683..rest_3714 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 2572 and 2580) then
    raise exception 'hotel codes hotel_2572..hotel_2580 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

