-- 7. links to hotels in `hotels`
create temp table _links_dk (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
insert into _links_dk values
    ('hotel_2572', 'rest_3700', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/copenhagen/dangleterre-copenhagen-7705 (Hotel d''Angleterre), a 2-Key hotel; restaurant pin 22 m from the hotel''s MICHELIN pin. 2026-10-30.');
do $$
declare n int;
begin
  select count(*) into n from _links_dk l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_dk l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'DK' and michelin_stars = 3;
  if n <> 3 then raise exception 'DK: expected 3 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'DK' and michelin_stars = 2;
  if n <> 6 then raise exception 'DK: expected 6 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'DK' and michelin_stars = 1;
  if n <> 32 then raise exception 'DK: expected 32 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'DK'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'DK: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'DK' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'DK: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'DK' and ah.guide_year > 2026;
  if n <> 0 then raise exception 'DK: % current star rows labelled after the 2026 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'DK' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'DK: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'DK' and michelin_keys = 3;
  if n <> 0 then raise exception 'DK: expected 0 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'DK' and michelin_keys = 2;
  if n <> 1 then raise exception 'DK: expected 1 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'DK' and michelin_keys = 1;
  if n <> 8 then raise exception 'DK: expected 8 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'DK' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'DK: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

-- ============================================================
-- FO: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026)
-- ============================================================

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'FO';
  if n <> 1 then raise exception 'FO: expected 1 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0480', 'PAZ')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'FO');
  if n <> 0 then raise exception 'FO: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'FO';
  if n <> 0 then raise exception 'FO: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

