-- post-conditions: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'SE' and michelin_stars = 3;
  if n <> 1 then raise exception 'SE: expected 1 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'SE' and michelin_stars = 2;
  if n <> 5 then raise exception 'SE: expected 5 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'SE' and michelin_stars = 1;
  if n <> 18 then raise exception 'SE: expected 18 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'SE'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'SE: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'SE' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'SE: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'SE' and ah.guide_year > 2026;
  if n <> 0 then raise exception 'SE: % current star rows labelled after the 2026 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'SE' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'SE: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'SE' and michelin_keys = 3;
  if n <> 0 then raise exception 'SE: expected 0 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'SE' and michelin_keys = 2;
  if n <> 1 then raise exception 'SE: expected 1 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'SE' and michelin_keys = 1;
  if n <> 10 then raise exception 'SE: expected 10 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'SE' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'SE: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

