    ('hotel_2597', 'rest_0431', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/stavanger/eilert-smith-hotel-9301 (Eilert Smith Hotel), a 1-Key hotel; restaurant pin 14 m from the hotel''s MICHELIN pin. 2026-10-30.');
do $$
declare n int;
begin
  select count(*) into n from _links_no l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_no l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'NO' and michelin_stars = 3;
  if n <> 2 then raise exception 'NO: expected 2 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'NO' and michelin_stars = 2;
  if n <> 2 then raise exception 'NO: expected 2 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'NO' and michelin_stars = 1;
  if n <> 17 then raise exception 'NO: expected 17 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'NO'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'NO: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'NO' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'NO: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'NO' and ah.guide_year > 2026;
  if n <> 0 then raise exception 'NO: % current star rows labelled after the 2026 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'NO' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'NO: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'NO' and michelin_keys = 3;
  if n <> 0 then raise exception 'NO: expected 0 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'NO' and michelin_keys = 2;
  if n <> 2 then raise exception 'NO: expected 2 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'NO' and michelin_keys = 1;
  if n <> 14 then raise exception 'NO: expected 14 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'NO' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'NO: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

-- ============================================================
-- FI: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026)
-- ============================================================

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'FI';
  if n <> 1 then raise exception 'FI: expected 1 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0433', 'Palace')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'FI');
  if n <> 0 then raise exception 'FI: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'FI';
  if n <> 0 then raise exception 'FI: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 3751 and 3757) then
    raise exception 'restaurant codes rest_3751..rest_3757 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 2607 and 2609) then
    raise exception 'hotel codes hotel_2607..hotel_2609 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

