-- 6. existing restaurants, fill-only (never overwrites)
create temp table _fill_fi (code text primary key, phone text, website_url text, michelin_url text, property_name text) on commit drop;
insert into _fill_fi values
    ('rest_0433', '+358 50 5020718', 'https://palacerestaurant.fi/', 'https://guide.michelin.com/en/uusimaa/helsinki/restaurant/palace', NULL);
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_fi f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_fi f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_fi f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_fi f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- post-conditions: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026), live listing; MICHELIN 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'FI' and michelin_stars = 3;
  if n <> 0 then raise exception 'FI: expected 0 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'FI' and michelin_stars = 2;
  if n <> 2 then raise exception 'FI: expected 2 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'FI' and michelin_stars = 1;
  if n <> 6 then raise exception 'FI: expected 6 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'FI'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'FI: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'FI' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'FI: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'FI' and ah.guide_year > 2026;
  if n <> 0 then raise exception 'FI: % current star rows labelled after the 2026 edition', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'FI' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'FI: % restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'FI' and michelin_keys = 3;
  if n <> 0 then raise exception 'FI: expected 0 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'FI' and michelin_keys = 2;
  if n <> 0 then raise exception 'FI: expected 0 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'FI' and michelin_keys = 1;
  if n <> 3 then raise exception 'FI: expected 3 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'FI' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys and a.guide_year = 2026) <> 1;
  if n <> 0 then raise exception 'FI: % Key hotels without exactly one matching current 2026 Key row', n; end if;
end $$;

-- ============================================================
-- IS: MICHELIN Guide Nordic Countries 2026 (Copenhagen, 1 June 2026)
-- ============================================================

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'IS';
  if n <> 0 then raise exception 'IS: expected 0 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from public.hotels where country_code = 'IS';
  if n <> 0 then raise exception 'IS: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 3758 and 3760) then
    raise exception 'restaurant codes rest_3758..rest_3760 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 2610 and 2614) then
    raise exception 'hotel codes hotel_2610..hotel_2614 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

